 const previousSubmit=form.onsubmit;form.onsubmit=e=>{if(!recipeEditor()&&form.elements.timerSessionId.value&&records.some(r=>r.timerSessionId===form.elements.timerSessionId.value&&r.id!==editing)){e.preventDefault();toast('呢次計時已儲存，請修改原紀錄，避免重複扣豆。');return}previousSubmit(e);if(!$('#editor').open&&session?.id===form.elements.timerSessionId.value){session=null;storeSession();updateSessionEntry()}};
