 const beanDialog=dialogFrame('bean-profile','咖啡豆資料',`<div class="fields">${inputField('title','咖啡豆名稱','text','required maxlength="160"')}${inputField('batch','批次／袋名（選填）','text','maxlength="100"')}${inputField('roaster','烘焙商')}${inputField('origin','產地／莊園')}${inputField('process','處理法')}<label>焙度<select name="roastLevel"><option value="">未註明</option><option>淺焙</option><option>中淺焙</option><option>中焙</option><option>中深焙</option><option>深焙</option></select></label>${inputField('roastedOn','烘焙日期','date')}${inputField('openedOn','開封日期','date')}${inputField('weight','本包起始重量 g（選填）','number','min="0" max="100000" step="0.1"')}</div><p class="hint">剩餘量＝起始重量−已連結紀錄嘅用粉量。修改同一筆紀錄會重新計算，唔會再扣一次。未記錄嘅耗豆未計入。</p><label>備註<textarea name="notes" rows="2"></textarea></label><label class="checkbox-row"><input name="linkOld" type="checkbox"> 將未連結批次、豆名完全相同嘅舊紀錄連到呢包豆</label><p id="bean-link-count" class="hint"></p><div class="form-bottom"><span>同款豆買第二包，可以新增另一個批次。</span><button type="submit" class="primary">儲存咖啡豆</button></div>`);
 let beanEditing=null;
 function openBean(id='',name=''){beanEditing=id||null;const f=beanDialog.querySelector('form');f.reset();const b=profiles().find(b=>b.id===id);if(b)Object.entries(b).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v??''});else f.elements.title.value=name;updateLinkCount();beanDialog.showModal()}
 function updateLinkCount(){const value=beanDialog.querySelector('form').elements.title.value.trim(),n=records.filter(r=>!r.beanId&&r.bean===value).length;$('#bean-link-count').textContent=`可連結 ${n} 筆未連結紀錄；勾選後先會加入呢包豆。`}
