 beanDialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f));values.title=values.title.trim();if(!values.title){toast('請填咖啡豆名稱');return}const bean={...values,id:beanEditing||uid('bean'),_beanProfile:true,weight:values.weight===''?null:Number(values.weight),date:localTime()};delete bean.linkOld;const nextBrews=records.map(r=>r.beanId===bean.id?{...r,bean:bean.title}:f.elements.linkOld.checked&&!r.beanId&&r.bean===bean.title?{...r,beanId:bean.id}:r);if(saveRows([...nextBrews,...customRecipes,...extras.filter(r=>r.id!==bean.id),bean])){beanDialog.close();page='beans';render();updateBeanPicker();toast('已儲存咖啡豆；庫存按連結紀錄計算。')}};
 const defaultsDialog=dialogFrame('coffee-defaults','常用設定',`<p class="hint">只套用到新紀錄，唔會覆蓋舊紀錄或已選食譜。可以之後手動修改。</p><label>常用咖啡豆<select name="beanId"></select></label><div class="fields"><label>常用器具<select name="method">${['Hario Switch','V60','Timemore B75','ORIGAMI','其他'].map(m=>`<option>${m}</option>`).join('')}</select></label>${inputField('dose','常用粉量 g','number','min="1" max="200" step="0.1" required')}${inputField('water','常用總注水 g','number','min="1" max="3000" step="0.1" required')}${inputField('temp','常用水溫 °C','number','min="1" max="100" step="0.1" required')}${inputField('clicks','常用 C40 格數','number','min="0" max="100" step="1" required')}${inputField('seconds','參考總時間 秒','number','min="1" max="3600" step="1" required')}${inputField('waterSource','常用水源／濾水設定')}</div><label class="checkbox-row"><input type="checkbox" name="keepMix"> 同時記住目前溝水／壺身設定作常用設定</label><p class="hint">器具設定唔等於分段食譜；有固定流程請另存食譜。常用設定登入後會同步。</p><div class="form-bottom"><span></span><button type="submit" class="primary">儲存常用設定</button></div>`);
 function openDefaults(){const f=defaultsDialog.querySelector('form'),p=prefs();f.reset();f.elements.beanId.innerHTML='<option value="">每次自行選擇</option>'+profiles().map(b=>`<option translate="no" value="${esc(b.id)}">${esc(b.title)}${b.batch?' · '+esc(b.batch):''}</option>`).join('');['dose','water','temp','clicks','seconds','method','beanId','waterSource'].forEach(k=>f.elements[k].value=p[k]??form.elements[k]?.value??'');defaultsDialog.showModal()}
 defaultsDialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f));delete values.keepMix;['dose','water','temp','clicks','seconds'].forEach(k=>values[k]=Number(values[k]));values.waterMix=f.elements.keepMix.checked?form.elements.waterMix.value:prefs().waterMix||'';if(saveExtra({id:'preferences',_preferences:true,values,date:localTime()})){defaultsDialog.close();toast('已儲存常用設定；下次新增紀錄會套用。')}};
 const saveRecipeDialog=dialogFrame('save-brew-recipe','將呢杯存成食譜',`${inputField('title','食譜名稱','text','required maxlength="160"')}<p class="hint">帶入目標參數、分段流程及溝水設定。唔會帶入評分、日期或實際量度值。</p><p id="recipe-save-note" class="hint"></p><div class="form-bottom"><span></span><button type="submit" class="primary">加入食譜收藏</button></div>`);
 let recipeSource=null;
