 saveRecipeDialog.querySelector('form').onsubmit=e=>{e.preventDefault();if(!recipeSource||!e.target.reportValidity())return;const title=e.target.elements.title.value.trim();if(!title)return;const saved=C.recipeFromBrew(recipeSource,uid('recipe'),title);if(saveRows([...records,...customRecipes,saved,...extras])){saveRecipeDialog.close();page='recipes';render();toast('已加入食譜收藏')}};
 // Guided timer. Timestamps preserve elapsed time after throttling/reload; alerts need an active browser.
 let account='loading',session=null,interval=null,alerted='',audio=null,wake=null;
 const timerDialog=document.createElement('dialog');timerDialog.id='guided-brew';timerDialog.setAttribute('aria-labelledby','guided-title');document.body.append(timerDialog);
