 function signal(){if(!session?.sound)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);g.gain.value=.12;o.frequency.value=660;o.start();o.stop(audio.currentTime+.15)}catch{}}
 function clockMS(ms){const sec=Math.floor(ms/1000);return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`}
 function resumeAvailable(){return session&&session.draft&&!records.some(r=>r.timerSessionId===session.id)}
 function updateSessionEntry(){timerLaunch.textContent=resumeAvailable()?'繼續上次沖煮 →':'開始逐步沖煮 →';document.querySelectorAll('[data-resume-session]').forEach(el=>el.hidden=!resumeAvailable())}
 function renderTimer(){if(!session)return;const s=session.plan[session.index],sum=session.plan.slice(0,session.index+1).reduce((n,x)=>n+(x.action==='注水'?Number(x.water):0),0);timerDialog.innerHTML=`<div class="dialog-head"><div><small>BREW ONE STEP AT A TIME</small><h2 id="guided-title">${session.finished?'沖煮完成':'逐步沖煮'}</h2></div><button type="button" class="icon" data-timer-close aria-label="收起沖煮計時">✕</button></div><p><span translate="no">${esc(session.draft.bean)}</span> · ${esc(session.draft.method)}</p><div class="guided-clock" id="guided-clock"></div><p class="guided-state" id="guided-state" role="status"></p>${session.finished?'<p class="guided-step">已完成所有段落</p>':`<span class="badge">第 ${session.index+1}／${session.plan.length} 段</span><h3 class="guided-step">${esc(s.action)}</h3><div class="guided-target">${s.action==='注水'?`本段加 <b>${fmt(s.water)}g</b><br>磅上累積 <b>${fmt(sum)}g</b>`:'呢段唔需要加水'}</div><div class="guided-facts"><span>${s.action==='注水'?fmt(s.temp||session.draft.temp)+'°C':'水溫沿用配方'}</span>${session.draft.method==='Hario Switch'?`<strong>Switch ${esc(s.valve)}閥</strong>`:''}</div><p ${recipes.some(r=>(r.recipeTemplate||r.title)===session.draft.recipeTemplate)?'':'translate="no"'}>${esc(s.note||'')}</p><p class="hint">參考開始 ${esc(s.start)} · ${s.next==='指定時間'?'等至總時間 '+esc(s.until):esc(s.next)}；由你確認完成本段，唔會自動跳過注水。</p>${s.action==='注水'?`<label>本段實際加水 g（選填；未量度留空）<input id="guided-water" value="${esc(session.stageWater?.[session.index]||'')}" type="number" min="0.1" max="3000" step="0.1" inputmode="decimal"></label>`:''}`}<div class="guided-actions">${session.finished?'<button type="button" class="primary" data-timer-review>填寫品飲及儲存 →</button>':`<button type="button" data-timer-pause>${session.running?'暫停':'繼續'}</button><button type="button" class="primary" data-timer-next>${session.index===session.plan.length-1?'完成沖煮':'完成本段 →'}</button>`}<button type="button" data-timer-sound>${session.sound?'關閉':'開啟'}提示音</button></div><p class="hint">收起畫面後仍按時間計算；鎖屏／切換 App 時提示音及亮屏未必可用。返回後會按經過時間更新。</p><details><summary>結束本次計時</summary><p class="hint">放棄只會清除此計時草稿，唔會新增沖煮紀錄或扣豆。</p><button type="button" data-timer-discard>放棄本次計時</button></details>`;tick();}
 function tick(){if(!session)return;const ms=C.elapsed(session,Date.now());$('#guided-clock').textContent=clockMS(ms);const s=session.plan[session.index],until=!session.finished&&s.next==='指定時間'?C.time(s.until):null;const due=until==null?null:until*1000-ms;$('#guided-state').textContent=session.finished?'完成時間 '+clockMS(session.elapsedMs):!session.running?'已暫停':due==null?'等實際完成後按「完成本段」':due>0?'距離參考時間 '+clockMS(due):'已到參考時間，請確認本段狀態';if(session.running&&due!=null&&due<=0&&alerted!==session.id+':'+session.index){alerted=session.id+':'+session.index;signal()}}
 function showTimer(){if(!resumeAvailable())return;renderTimer();if(!timerDialog.open)timerDialog.showModal();clearInterval(interval);interval=setInterval(tick,250);if(session.running)acquireWake()}
 function snapshotForm(){const row=Object.fromEntries(new FormData(form));['dose','water','temp','clicks','seconds','ice'].forEach(k=>row[k]=Number(row[k]||0));row.stages=clone(stages);return row}
 timerLaunch.onclick=()=>{if(account==='loading'){toast('請等帳戶狀態確認後再開始計時。');return}if(resumeAvailable()){showTimer();return}if(recipeEditor()||!form.reportValidity())return;const draft=snapshotForm();try{C.validatePlan(draft)}catch(e){toast(e.message);advanced.open=true;return}session={version:1,id:uid('session'),draft:C.rebrew(draft),plan:C.stageCopy(draft.stages),index:0,running:true,startedAt:Date.now(),elapsedMs:0,measurements:[],finished:false,sound:false};alerted='';if(!writeJSON(timerKey(),session)){session=null;return}showTimer();updateSessionEntry()};
