 timerDialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!session)return;if(b.hasAttribute('data-timer-close')){timerDialog.close();releaseWake();return}if(b.hasAttribute('data-timer-pause')){session.elapsedMs=C.elapsed(session,Date.now());session.running=!session.running;session.startedAt=Date.now();storeSession();if(session.running)acquireWake();else releaseWake();renderTimer()}
  if(b.hasAttribute('data-timer-sound')){session.sound=!session.sound;storeSession();signal();renderTimer()}
  if(b.hasAttribute('data-timer-next')){if(!session.running){toast('請先繼續計時再完成本段。');return}const input=$('#guided-water');if(input&&!input.reportValidity())return;session.measurements[session.index]={actualWater:input?.value||'',actualTime:clockMS(C.elapsed(session,Date.now()))};if(session.index===session.plan.length-1){session.elapsedMs=C.elapsed(session,Date.now());session.running=false;session.finished=true;session.finishedAt=localTime();releaseWake()}else session.index++;storeSession();renderTimer()}
  if(b.hasAttribute('data-timer-review')){const draft={...C.rebrew(session.draft),timerSessionId:session.id,actualSeconds:Math.round(session.elapsedMs/100)/10,finishedAt:session.finishedAt,stages:session.plan.map((s,i)=>({...s,...session.measurements[i]}))};const pours=draft.stages.filter(s=>s.action==='注水');draft.actualWater=pours.length&&pours.every(s=>s.actualWater!=='')?Math.round(pours.reduce((n,s)=>n+Number(s.actualWater),0)*10)/10:'';timerDialog.close();openBrew(draft);advanced.open=false;actualComparison();toast('實際時間已帶入；儲存紀錄後先計入用豆量。')}
  if(b.hasAttribute('data-timer-discard')){session=null;storeSession();timerDialog.close();clearInterval(interval);releaseWake();updateSessionEntry();render()}
 });
